import{_ as o,c as e,o as t,ag as a}from"./chunks/framework.DPDPlp3K.js";const u=JSON.parse('{"title":"公共免费 Webhook 接收端工具全指南","description":"","frontmatter":{},"headers":[],"relativePath":"notion/公共免费 Webhook 接收端盘点：从在线调试到本地开发/2.md","filePath":"notion/公共免费 Webhook 接收端盘点：从在线调试到本地开发/2.md"}'),i={name:"notion/公共免费 Webhook 接收端盘点：从在线调试到本地开发/2.md"};function r(h,l,n,b,s,d){return t(),e("div",null,l[0]||(l[0]=[a('<h1 id="公共免费-webhook-接收端工具全指南" tabindex="-1">公共免费 Webhook 接收端工具全指南 <a class="header-anchor" href="#公共免费-webhook-接收端工具全指南" aria-label="Permalink to &quot;公共免费 Webhook 接收端工具全指南&quot;">​</a></h1><h2 id="一、前言" tabindex="-1">一、前言 <a class="header-anchor" href="#一、前言" aria-label="Permalink to &quot;一、前言&quot;">​</a></h2><p>开发、调试 Webhook 时，我们经常需要一个临时公网地址接收第三方推送的数据（GitHub、支付平台、CI/CD、钉钉/企业微信机器人等）。 自建服务成本高、本地无公网IP，因此各类<strong>免费公共 Webhook 接收站点</strong>成为调试首选。 本文整理海内外可用、零成本开箱即用的接收工具，区分国内直连、海外稳定两类，并说明适用场景、优缺点与安全规范。</p><blockquote><p>核心用途：临时捕获 POST 请求、查看完整 Header / JSON Body、溯源请求IP、模拟回调测试。</p></blockquote><h2 id="二、海外免费工具-适合-github、stripe、海外云服务-需代理访问" tabindex="-1">二、海外免费工具（适合 GitHub、Stripe、海外云服务，需代理访问） <a class="header-anchor" href="#二、海外免费工具-适合-github、stripe、海外云服务-需代理访问" aria-label="Permalink to &quot;二、海外免费工具（适合 GitHub、Stripe、海外云服务，需代理访问）&quot;">​</a></h2><h3 id="_1-webhook-site-行业标杆-最常用" tabindex="-1">1. webhook.site（行业标杆，最常用） <a class="header-anchor" href="#_1-webhook-site-行业标杆-最常用" aria-label="Permalink to &quot;1. webhook.site（行业标杆，最常用）&quot;">​</a></h3><ul><li>官网：<a href="https://webhook.site" target="_blank" rel="noreferrer">https://webhook.site</a></li><li>核心特性 <ol><li>无需注册，打开页面自动生成唯一 HTTPS 监听地址；</li><li>实时展示完整请求：请求头、Query 参数、Body、来源IP、UA；</li><li>JSON 自动格式化高亮，支持一键复制 payload；</li><li>可自定义接口返回状态码、返回文本，模拟服务回调。</li></ol></li><li>免费限制 <ul><li>匿名会话有效期 24h，最多存储 50 条请求记录；</li><li>超时后所有请求记录自动清空。</li></ul></li><li>适用场景：临时快速查看推送原始数据、短期调试海外平台 Webhook。</li><li>缺点：国内裸连访问缓慢或打不开。</li></ul><h3 id="_2-hook0-play-大容量匿名接收端" tabindex="-1">2. Hook0 Play（大容量匿名接收端） <a class="header-anchor" href="#_2-hook0-play-大容量匿名接收端" aria-label="Permalink to &quot;2. Hook0 Play（大容量匿名接收端）&quot;">​</a></h3><ul><li>官网：<a href="https://play.hook0.com" target="_blank" rel="noreferrer">https://play.hook0.com</a></li><li>核心特性 <ol><li>免登录即用，免费匿名会话支持存储 1000 条请求，远超同类工具；</li><li>自带转发能力，一键将 Webhook 流量转发到本地 <code>localhost</code>；</li><li>项目开源，可自行私有化部署；</li><li>支持历史请求重放，方便重复测试逻辑。</li></ol></li><li>适用场景：高频推送、长时间持续调试、本地开发流量转发。</li></ul><h3 id="_3-webhook-relay-bin-自带本地隧道-替代-ngrok" tabindex="-1">3. Webhook Relay Bin（自带本地隧道，替代 ngrok） <a class="header-anchor" href="#_3-webhook-relay-bin-自带本地隧道-替代-ngrok" aria-label="Permalink to &quot;3. Webhook Relay Bin（自带本地隧道，替代 ngrok）&quot;">​</a></h3><ul><li>官网：<a href="https://webhookrelay.com/webhook-bin/" target="_blank" rel="noreferrer">https://webhookrelay.com/webhook-bin/</a></li><li>核心特性 <ol><li>免注册生成临时监听 URL；</li><li>内置 CLI 工具，捕获到请求后自动转发到本机开发端口；</li><li>支持重放历史请求、自定义响应内容、过滤请求日志。</li></ol></li><li>适用场景：本地项目调试，不想额外安装 ngrok / cloudflare tunnel。</li></ul><h3 id="_4-svix-play-专业-webhook-签名校验工具" tabindex="-1">4. Svix Play（专业 Webhook 签名校验工具） <a class="header-anchor" href="#_4-svix-play-专业-webhook-签名校验工具" aria-label="Permalink to &quot;4. Svix Play（专业 Webhook 签名校验工具）&quot;">​</a></h3><ul><li>官网：<a href="https://play.svix.com" target="_blank" rel="noreferrer">https://play.svix.com</a></li><li>核心特性 <ol><li>专为标准化 Webhook 设计，内置 HMAC 签名校验面板；</li><li>适配 Stripe、海外SaaS支付、第三方登录等带签名回调；</li><li>配套官方 CLI，支持流量本地转发。</li></ol></li><li>适用场景：调试带密钥签名的支付、第三方业务回调，校验请求合法性。</li></ul><h3 id="_5-hooklistener-永久匿名地址" tabindex="-1">5. HookListener（永久匿名地址） <a class="header-anchor" href="#_5-hooklistener-永久匿名地址" aria-label="Permalink to &quot;5. HookListener（永久匿名地址）&quot;">​</a></h3><ul><li>官网：<a href="https://www.hooklistener.com" target="_blank" rel="noreferrer">https://www.hooklistener.com</a></li><li>核心特性 <ol><li>匿名生成的链接不会随浏览器关闭失效；</li><li>无硬性请求数量限流，长期保存请求记录；</li><li>界面简洁无广告，一键重放任意历史请求。</li></ol></li><li>适用场景：需要长期固定临时地址，频繁切换浏览器调试。</li></ul><h2 id="三、国内直连免费工具-无需代理-适配钉钉-企业微信-阿里云-腾讯云" tabindex="-1">三、国内直连免费工具（无需代理，适配钉钉/企业微信/阿里云/腾讯云） <a class="header-anchor" href="#三、国内直连免费工具-无需代理-适配钉钉-企业微信-阿里云-腾讯云" aria-label="Permalink to &quot;三、国内直连免费工具（无需代理，适配钉钉/企业微信/阿里云/腾讯云）&quot;">​</a></h2><h3 id="_1-uu在线工具-webhook-监听" tabindex="-1">1. UU在线工具 Webhook 监听 <a class="header-anchor" href="#_1-uu在线工具-webhook-监听" aria-label="Permalink to &quot;1. UU在线工具 Webhook 监听&quot;">​</a></h3><ul><li>地址：<a href="https://uutool.cn/webhook/" target="_blank" rel="noreferrer">https://uutool.cn/webhook/</a></li><li>核心特性 <ol><li>国内服务器部署，国内网络无延迟直连；</li><li>一键启动监听，自动生成 HTTPS 公网地址；</li><li>完整记录请求时间、来源IP、请求头、表单/JSON载荷；</li><li>支持自定义接口返回内容、状态码。</li></ol></li><li>免费限制：半小时无新请求自动销毁链接，清空数据。</li><li>适用场景：国内企业微信、钉钉机器人、腾讯云/阿里云告警回调调试。</li></ul><h3 id="_2-webtoolsplanet-webhook-tester" tabindex="-1">2. WebtoolsPlanet Webhook Tester <a class="header-anchor" href="#_2-webtoolsplanet-webhook-tester" aria-label="Permalink to &quot;2. WebtoolsPlanet Webhook Tester&quot;">​</a></h3><ul><li>地址：<a href="https://webtoolsplanet.com/developer/webhook-tester" target="_blank" rel="noreferrer">https://webtoolsplanet.com/developer/webhook-tester</a></li><li>核心特性 <ol><li>免登录打开即用，轻量化页面加载快；</li><li>自动解析 JSON、表单数据，区分 GET/POST 请求；</li><li>会话有效期 2h，最多保存 50 条请求。</li></ol></li><li>适用场景：极简快速调试国内各类云服务回调。</li></ul><h2 id="四、小众轻量化免费工具-按需选用" tabindex="-1">四、小众轻量化免费工具（按需选用） <a class="header-anchor" href="#四、小众轻量化免费工具-按需选用" aria-label="Permalink to &quot;四、小众轻量化免费工具（按需选用）&quot;">​</a></h2><ol><li>HookTest.dev <ul><li>地址：<a href="https://hooktest.dev/" target="_blank" rel="noreferrer">https://hooktest.dev/</a></li><li>特性：24h有效期，单链接最多100条记录，支持自动转发消息到钉钉、Discord。</li></ul></li><li>Catchhook.app <ul><li>地址：<a href="https://temp.catchhook.app/" target="_blank" rel="noreferrer">https://temp.catchhook.app/</a></li><li>特性：临时链接有效期48h，提供 Shell / Node 转发命令。</li></ul></li><li>MockLab（长期固定端点，需注册） <ul><li>地址：<a href="https://mocklab.dev/" target="_blank" rel="noreferrer">https://mocklab.dev/</a></li><li>特性：免费注册赠送1个永久Webhook地址，每日200次请求额度，适合长期稳定调试。</li></ul></li></ol><h2 id="五、工具选型对照表" tabindex="-1">五、工具选型对照表 <a class="header-anchor" href="#五、工具选型对照表" aria-label="Permalink to &quot;五、工具选型对照表&quot;">​</a></h2><table tabindex="0"><thead><tr><th>使用需求</th><th>推荐工具</th><th>核心优势</th></tr></thead><tbody><tr><td>短期临时查看海外平台payload</td><td>webhook.site</td><td>开箱即用，JSON格式化优秀</td></tr><tr><td>国内环境、无代理调试</td><td>UU在线工具Webhook</td><td>国内服务器直连，低延迟</td></tr><tr><td>高频大量推送、存储多条日志</td><td>Hook0 Play</td><td>免费支持1000条请求记录</td></tr><tr><td>本地开发，需要转发到localhost</td><td>Webhook Relay Bin / Hook0 Play</td><td>自带流量转发，不用隧道工具</td></tr><tr><td>调试支付带签名校验的回调</td><td>Svix Play</td><td>内置HMAC签名验证面板</td></tr><tr><td>需要长期固定不变的监听地址</td><td>MockLab（注册）/ HookListener</td><td>链接长期有效，不自动销毁</td></tr></tbody></table><h2 id="六、标准使用流程-以-webhook-site-为例" tabindex="-1">六、标准使用流程（以 webhook.site 为例） <a class="header-anchor" href="#六、标准使用流程-以-webhook-site-为例" aria-label="Permalink to &quot;六、标准使用流程（以 webhook.site 为例）&quot;">​</a></h2><ol><li>打开官网，复制页面顶部生成的唯一 HTTPS 监听 URL；</li><li>进入第三方平台（GitHub / 支付后台 / 钉钉机器人），填入该地址作为 Webhook 回调地址；</li><li>触发对应事件（代码提交、支付完成、表单提交）；</li><li>页面实时捕获 POST 请求，展开查看完整请求头、JSON 载荷、来源IP；</li><li>复制 payload 到本地脚本，模拟回调重复测试业务逻辑。</li></ol><h2 id="七、重要安全规范-必看" tabindex="-1">七、重要安全规范（必看） <a class="header-anchor" href="#七、重要安全规范-必看" aria-label="Permalink to &quot;七、重要安全规范（必看）&quot;">​</a></h2><ol><li><strong>禁止传入生产敏感数据</strong> 所有公共 Webhook 站点拥有请求数据查看权限，不要推送明文密钥、用户隐私、支付订单敏感信息，仅用于开发测试环境。</li><li><strong>匿名会话有生命周期</strong> 绝大多数免登录临时链接会在 0.5~48h 自动清空记录，长期调试建议注册账号保存端点。</li><li><strong>生产环境严禁依赖公共接收端</strong> 公共工具仅作调试；正式业务接收 Webhook 需要自建接口，配置 HMAC 签名校验、来源IP白名单、请求参数过滤，防止伪造攻击。</li><li><strong>海外工具访问限制</strong> webhook.site 等海外站点国内裸连大概率无法访问，调试国内业务优先选择国内工具。</li></ol><h2 id="八、补充-本地无公网替代方案" tabindex="-1">八、补充：本地无公网替代方案 <a class="header-anchor" href="#八、补充-本地无公网替代方案" aria-label="Permalink to &quot;八、补充：本地无公网替代方案&quot;">​</a></h2><p>如果不想使用第三方公共站点，可通过隧道工具把本地端口暴露为公网地址，自建临时接收端：</p><ul><li>ngrok</li><li>Cloudflare Tunnel</li><li>VS Code Port Forwarding 优势：数据完全留在本地，无第三方泄露风险，适合处理敏感调试数据。</li></ul>',31)]))}const c=o(i,[["render",r]]);export{u as __pageData,c as default};
